    """
    This function finds the maximum length of the subsequence with difference between adjacent elements.

    Args:
        arr (list): A list of integers.
        k (int): The maximum allowed difference between adjacent elements.

    Returns:
        int: The maximum length of the subsequence with difference between adjacent elements.

    Raises:
        TypeError: If the input array is not a list or if the second parameter is not an integer.
    """
    if not isinstance(arr, list):
        raise TypeError("Input array must be a list")
    if not all(isinstance(x, int) for x in arr):
        raise TypeError("Input array must contain only integers")
    if not isinstance(k, int):
        raise TypeError("Second parameter must be an integer")

    if not arr or k < 1:
        return 0

    max_length = 1
    current_length = 1
    previous_diff = arr[0]

    for i in range(1, len(arr)):
        diff = abs(arr[i] - arr[i - 1])
        if diff == 0:
            current_length = 1
        elif diff == previous_diff:
            current_length += 1
        elif diff <= k:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 2
        previous_diff = diff

    return max(max_length, current_length)


